import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.DoRPXVp_.js";const p=JSON.parse('{"title":"Lattice Internal Architecture Guide","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),o={name:"architecture.md"};function n(s,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="lattice-internal-architecture-guide" tabindex="-1">Lattice Internal Architecture Guide <a class="header-anchor" href="#lattice-internal-architecture-guide" aria-label="Permalink to &quot;Lattice Internal Architecture Guide&quot;">​</a></h1><h2 id="core-philosophy" tabindex="-1">Core Philosophy <a class="header-anchor" href="#core-philosophy" aria-label="Permalink to &quot;Core Philosophy&quot;">​</a></h2><h3 id="network-as-code" tabindex="-1">Network as Code <a class="header-anchor" href="#network-as-code" aria-label="Permalink to &quot;Network as Code&quot;">​</a></h3><p>Networking topology is defined via Kubernetes CRDs, eliminating manual tunnel configuration and static firewall rules.</p><hr><h3 id="separation-of-planes" tabindex="-1">Separation of Planes <a class="header-anchor" href="#separation-of-planes" aria-label="Permalink to &quot;Separation of Planes&quot;">​</a></h3><ul><li><strong>Control Plane</strong>: Powered by the K8s API; manages identity, IPAM (IP Address Management), and policy orchestration.</li><li><strong>Data Plane</strong>: Powered by WireGuard + eBPF; handles high-speed encryption and kernel-level access control.</li></ul><hr><h3 id="zero-trust-networking" tabindex="-1">Zero-Trust Networking <a class="header-anchor" href="#zero-trust-networking" aria-label="Permalink to &quot;Zero-Trust Networking&quot;">​</a></h3><p>No peer is trusted by default. Access is granted based on <strong>identity (Labels)</strong> rather than IP addresses.</p><h2 id="core-objects" tabindex="-1">Core Objects <a class="header-anchor" href="#core-objects" aria-label="Permalink to &quot;Core Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object (CRD)</th><th>Scope</th><th>Relationship</th><th>Core Responsibility</th></tr></thead><tbody><tr><td><strong>LatticeGlobalIPPool</strong></td><td>Cluster</td><td>1 : N (Namespaces)</td><td>Defines the cluster IP Pool, All LatticeNetwork get CIDR from here.</td></tr><tr><td><strong>LatticeNetwork</strong></td><td>Namespaced</td><td>1 : N (Namespaces)</td><td>Defines then namespace Overlay CIDR, Global Routing ID, and MTU settings</td></tr><tr><td><strong>Namespace</strong></td><td>Namespaced</td><td>1 : 1 (Network)</td><td>Logical grouping. Linked to a Network via the label <code>lattice.io/network</code>.</td></tr><tr><td><strong>LatticeNetworkPeering</strong></td><td>CLuster</td><td>1 : N (Namespaces)</td><td>Defines two networks connected each other, using NetworkPeering</td></tr><tr><td><strong>LatticePeer</strong></td><td>Namespaced</td><td>N : 1 (Namespace)</td><td>Represents an endpoint (Pod, IoT, PC). Holds PublicKeys and VIPs.</td></tr><tr><td><strong>LatticePolicy</strong></td><td>Namespaced</td><td>N : 1 (Network)</td><td>The &quot;Security Group.&quot; Defines Ingress/Egress rules between Peers.</td></tr></tbody></table><h2 id="data-plane-implementation" tabindex="-1">Data Plane Implementation <a class="header-anchor" href="#data-plane-implementation" aria-label="Permalink to &quot;Data Plane Implementation&quot;">​</a></h2><h2 id="_3-1-multi-tenancy-via-policy-routing" tabindex="-1">3.1 Multi-Tenancy via Policy Routing <a class="header-anchor" href="#_3-1-multi-tenancy-via-policy-routing" aria-label="Permalink to &quot;3.1 Multi-Tenancy via Policy Routing&quot;">​</a></h2><p>To run multiple isolated Networks on a single <code>wg0</code> interface, Lattice utilizes <strong>Linux Policy Routing</strong>:</p><ul><li><strong>FWMARK Tagging</strong>: When a packet enters <code>wg0</code> or originates from a Pod, an eBPF program tags the packet with a Network ID (Mark).</li><li><strong>Isolated Routing Tables</strong>: The kernel selects a specific routing table based on the tag.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Each Network has its own dedicated routing table</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lookup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> table</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><ul><li><strong>Conflict Resolution</strong> : If two Networks use overlapping CIDRs (e.g., both use 10.0.0.0/24), eBPF performs 1:1 DNAT (Static NAT) at the interface boundary to map them into unique &quot;Shadow IP&quot; spaces during cross-network peering.</li></ul><h2 id="ebpf-powered-security" tabindex="-1">eBPF-Powered Security <a class="header-anchor" href="#ebpf-powered-security" aria-label="Permalink to &quot;eBPF-Powered Security&quot;">​</a></h2><p>LatticePolicy is compiled into eBPF Maps rather than iptables rules:</p><ul><li>Source Validation: Verifies that the SrcIP of an incoming decrypted packet matches the PublicKey of the sender.</li><li>Line-Speed Filtering: Blocks unauthorized L4 (Port/Protocol) access directly in the kernel, ensuring near-zero latency overhead.</li></ul><h2 id="software-components" tabindex="-1">Software Components <a class="header-anchor" href="#software-components" aria-label="Permalink to &quot;Software Components&quot;">​</a></h2><h3 id="binary-distribution-strategy" tabindex="-1">Binary Distribution Strategy <a class="header-anchor" href="#binary-distribution-strategy" aria-label="Permalink to &quot;Binary Distribution Strategy&quot;">​</a></h3><ul><li>lattice-server (The Controller) <ul><li>Dependencies: client-go, controller-runtime.</li><li>Role: The &quot;Brain.&quot; Watches CRDs, runs the Registration API, and manages the global IPAM pool.</li></ul></li><li>lattice (The Lean Agent) <ul><li>Dependencies: wireguard-go, ebpf-manager.</li><li>Role: The &quot;Muscle.&quot; Runs on IoT/PC/Nodes. It communicates with the Server via REST/gRPC (no K8s SDK) to pull configurations and manage the local wg0 interface.</li><li>Optimization: By removing K8s dependencies, the binary size is kept under 12MB.</li></ul></li></ul><h3 id="the-join-lifecycle" tabindex="-1">The &quot;Join&quot; Lifecycle <a class="header-anchor" href="#the-join-lifecycle" aria-label="Permalink to &quot;The &quot;Join&quot; Lifecycle&quot;">​</a></h3><ul><li>Register: User runs <code>lattice join --network finance --token &lt;T&gt;</code>.</li><li>Auth: The Agent generates a KeyPair, uploads the PublicKey. The Server creates a LatticePeer resource in the designated Namespace.</li><li>Sync: The Server pushes the Peer list (only for that Network) to the Agent.</li><li>Connect: The Agent configures wg0 and establishes encrypted P2P tunnels.</li></ul><h2 id="industrial-grade-connectivity" tabindex="-1">Industrial-Grade Connectivity <a class="header-anchor" href="#industrial-grade-connectivity" aria-label="Permalink to &quot;Industrial-Grade Connectivity&quot;">​</a></h2><ul><li>NAT Traversal: Integrates STUN/ICE protocols. If peers are behind symmetric NATs, the system automatically fails over to RELAY Mode (via an encrypted TURN-like relay).</li><li>Roaming Support: Leverages WireGuard’s mobility. If a mobile device switches from Wi-Fi to 5G, the tunnel stays alive seamlessly with the same Virtual IP (VIP).</li></ul><h2 id="developer-maintenance-checklist" tabindex="-1">Developer Maintenance Checklist <a class="header-anchor" href="#developer-maintenance-checklist" aria-label="Permalink to &quot;Developer Maintenance Checklist&quot;">​</a></h2><ul><li>API Evolution: Changes to LatticeNetwork must be backward compatible, as edge agents may run older versions.</li><li>Observability: Use lattice status for local health checks and kubectl get wfpeer -A for global topology visualization.</li><li>Audit Logs: Denied connections are captured by eBPF and reported asynchronously to the Server for security auditing.</li></ul>`,30)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
